import { resolve as resolvePath } from "node:path";
import { DEFAULT_APP_CONFIG } from "./config.js";
import { runExportCommand, type CliOptions } from "./commands.js";
import { runInteractiveCli } from "./interactive.js";
import type { RuntimeExtractionMethod, RuntimeProvider } from "../types/runtime.js";

const HELP_TEXT = `Chat Exporter

Usage:
  node dist/app/cli.js [options]

Options:
  --interactive               Launch the guided interactive menu
  --cdp-url <url>             CDP HTTP endpoint (default: ${DEFAULT_APP_CONFIG.cdpUrl})
  --output-dir <path>         Output directory (default: ${DEFAULT_APP_CONFIG.outputDir})
  --provider <chatgpt|claude> Restrict selection to one provider
  --url <url>                 Export the tab matching the exact or prefixed URL
  --tab-index <n>             Export one supported tab by 1-based index after provider filtering
  --all-tabs                  Export every matched supported tab
  --current-tab               Require a single matched supported tab; fail if ambiguous
  --preferred-method <internal_fetch|dom_parse|ui_copy>
                              Prefer one extraction method first
  --help                      Show this help

Notes:
  - Launch Chromium/Chrome/Edge/Brave with remote debugging enabled first.
  - Example: chrome --remote-debugging-port=9222
  - Without --all-tabs, the CLI refuses ambiguous multi-tab matches.
`;

function parseProvider(value: string): RuntimeProvider {
  if (value === "chatgpt" || value === "claude") {
    return value;
  }
  throw new Error(`Unsupported provider: ${value}`);
}

function parsePreferredMethod(value: string): RuntimeExtractionMethod {
  if (value === "internal_fetch" || value === "dom_parse" || value === "ui_copy") {
    return value;
  }
  throw new Error(`Unsupported extraction method: ${value}`);
}

function parseArgs(argv: string[]): CliOptions {
  const options: CliOptions = {
    cdpUrl: DEFAULT_APP_CONFIG.cdpUrl,
    outputDir: resolvePath(DEFAULT_APP_CONFIG.outputDir),
    allTabs: false,
    currentTab: false,
    help: false,
    interactive: false
  };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    switch (token) {
      case "--help":
      case "-h":
        options.help = true;
        break;
      case "--interactive":
        options.interactive = true;
        break;
      case "--cdp-url": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --cdp-url");
        options.cdpUrl = value;
        index += 1;
        break;
      }
      case "--output-dir": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --output-dir");
        options.outputDir = resolvePath(value);
        index += 1;
        break;
      }
      case "--provider": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --provider");
        options.provider = parseProvider(value);
        index += 1;
        break;
      }
      case "--url": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --url");
        options.url = value;
        index += 1;
        break;
      }
      case "--tab-index": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --tab-index");
        const parsed = Number.parseInt(value, 10);
        if (!Number.isInteger(parsed) || parsed < 1) {
          throw new Error(`Invalid tab index: ${value}`);
        }
        options.tabIndex = parsed;
        index += 1;
        break;
      }
      case "--all-tabs":
        options.allTabs = true;
        break;
      case "--current-tab":
        options.currentTab = true;
        break;
      case "--preferred-method": {
        const value = argv[index + 1];
        if (!value) throw new Error("Missing value for --preferred-method");
        options.preferredMethod = parsePreferredMethod(value);
        index += 1;
        break;
      }
      default:
        throw new Error(`Unknown argument: ${token}`);
    }
  }

  return options;
}

async function main(): Promise<void> {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    process.stdout.write(HELP_TEXT);
    return;
  }

  if (options.interactive) {
    await runInteractiveCli();
    return;
  }

  const result = await runExportCommand(options);

  if (result.exported.length > 0) {
    for (const exported of result.exported) {
      process.stdout.write(
        `Exported ${exported.provider}: ${exported.conversationTitle}\n` +
        `  JSON: ${exported.jsonPath}\n` +
        `  Markdown: ${exported.markdownPath}\n`
      );
    }
  }

  if (result.errors.length > 0) {
    for (const error of result.errors) {
      process.stderr.write(`${error}\n`);
    }
  }

  if (!result.success) {
    process.exitCode = 1;
  }
}

main().catch((error) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`${message}\n`);
  process.stderr.write(`${HELP_TEXT}\n`);
  process.exitCode = 1;
});
