import type { RuntimeExtractionResult } from "../../types/runtime.js";
import { BaseExtractor } from "../shared/base-extractor.js";
import { CHATGPT_INTERNAL_FETCH_PATHS } from "./constants.js";
import { parseChatGPTConversationId } from "./detect.js";
import { buildChatGPTRuntimeResult } from "./map-runtime.js";

interface ChatGPTConversationPayload {
  title?: string | null;
  current_node?: string | null;
  mapping?: Record<string, {
    id?: string;
    parent?: string | null;
    message?: {
      id?: string;
      author?: { role?: string | null };
      create_time?: number | null;
      content?: {
        content_type?: string | null;
        parts?: string[];
      } | null;
    } | null;
  }>;
}

export class ChatGPTInternalFetchExtractor<TPage extends BrowserPageLike = BrowserPageLike> extends BaseExtractor<TPage> {
  public readonly provider = "chatgpt" as const;
  public readonly method = "internal_fetch" as const;

  public async canExtract(input: ExtractorContext<TPage>): Promise<boolean> {
    return parseChatGPTConversationId(input.pageUrl) !== null;
  }

  public async extract(input: ExtractorContext<TPage>): Promise<RuntimeExtractionResult> {
    const conversationId = parseChatGPTConversationId(input.pageUrl);
    if (!conversationId) {
      throw new Error("ChatGPT conversation ID not found in URL.");
    }

    const pageTitle = input.pageTitle ?? await input.page.title();
    const payload = await input.page.evaluate<ChatGPTConversationPayload | null, { conversationId: string; paths: readonly string[] }>(
      async ({ conversationId, paths }) => {
        for (const prefix of paths) {
          const response = await fetch(`${prefix}${conversationId}`, {
            credentials: "include",
            headers: { "Content-Type": "application/json" }
          });
          if (response.ok) {
            return await response.json() as ChatGPTConversationPayload;
          }
        }
        return null;
      },
      { conversationId, paths: CHATGPT_INTERNAL_FETCH_PATHS }
    );

    if (!payload || !payload.mapping) {
      throw new Error("ChatGPT internal conversation fetch returned no usable payload.");
    }

    const messages = Object.values(payload.mapping)
      .map((node, index) => {
        const role: "human" | "assistant" | "unknown" = node.message?.author?.role === "user"
          ? "human"
          : node.message?.author?.role === "assistant"
            ? "assistant"
            : "unknown";
        const text = node.message?.content?.parts?.filter((part) => typeof part === "string").join("\n\n") ?? "";
        const createdAt = node.message?.create_time != null
          ? new Date(node.message.create_time * 1000).toISOString()
          : null;
        return {
          providerMessageId: node.message?.id ?? node.id ?? null,
          role,
          timestamp: createdAt,
          text,
          sequence: index
        };
      })
      .filter((message) => message.text.trim().length > 0);

    return buildChatGPTRuntimeResult({
      pageUrl: input.pageUrl,
      pageTitle,
      capturedAt: input.capturedAt,
      method: this.method,
      conversationId,
      title: payload.title ?? pageTitle,
      messages
    });
  }
