import type { RuntimeExtractionResult } from "../../types/runtime.js";
import { BaseExtractor } from "../shared/base-extractor.js";
import { normalizeDomText } from "../shared/dom-helpers.js";
import { CHATGPT_MESSAGE_SELECTOR } from "./constants.js";
import { buildChatGPTRuntimeResult } from "./map-runtime.js";
import { parseChatGPTConversationId } from "./detect.js";

type DomMessage = {
  providerMessageId: string | null;
  role: "human" | "assistant" | "unknown";
  text: string;
  sequence: number;
};

export class ChatGPTDomExtractor<TPage extends BrowserPageLike = BrowserPageLike> extends BaseExtractor<TPage> {
  public readonly provider = "chatgpt" as const;
  public readonly method = "dom_parse" as const;

  public async canExtract(input: ExtractorContext<TPage>): Promise<boolean> {
    const count = await input.page.locator(CHATGPT_MESSAGE_SELECTOR).count();
    return count > 0;
  }

  public async extract(input: ExtractorContext<TPage>): Promise<RuntimeExtractionResult> {
    const pageTitle = input.pageTitle ?? await input.page.title();
    const conversationId = parseChatGPTConversationId(input.pageUrl);
    const domMessages = await input.page.evaluate<DomMessage[], string>((selector) => {
      const nodes = Array.from(document.querySelectorAll<HTMLElement>(selector));
      return nodes.map((node, index) => {
        const roleAttr = node.getAttribute("data-message-author-role");
        const role = roleAttr === "user" ? "human" : roleAttr === "assistant" ? "assistant" : "unknown";
        return {
          providerMessageId: node.getAttribute("data-message-id") ?? null,
          role,
          text: node.innerText ?? "",
          sequence: index
        };
      });
    }, CHATGPT_MESSAGE_SELECTOR);

    return buildChatGPTRuntimeResult({
      pageUrl: input.pageUrl,
      pageTitle,
      capturedAt: input.capturedAt,
      method: this.method,
      conversationId,
      title: pageTitle,
      messages: domMessages.map((message) => ({
        providerMessageId: message.providerMessageId,
        role: message.role,
        text: normalizeDomText(message.text),
        sequence: message.sequence
      }))
    });
  }
}
