  ExtractionReconciler,
  ReconciliationEvent,
  ReconciliationFailure,
  ReconciliationInput,
  ReconciliationOutcome,
  ReconciliationResult
} from "../domain/reconciliation.js";
import type { RuntimeArtifact, RuntimeContentBlock, RuntimeExtractionMethod, RuntimeMessage, RuntimeNormalizedArtifact, RuntimeNormalizedConversation, RuntimeNormalizedMessage, RuntimeRole } from "../types/runtime.js";
import { DefaultRuntimeValidator } from "../validation/runtime-validator.js";
import { normalizeIsoTimestamp } from "../utils/dates.js";
import { nonEmptyOrNull, isPlaceholderTitle, normalizeWhitespace, slugify } from "../utils/strings.js";
import { createRuntimeId } from "../utils/ids.js";

const METHOD_RANK: Record<RuntimeExtractionMethod, number> = {
  internal_fetch: 1,
  dom_parse: 2,
  ui_copy: 3,
  mixed: 4
};

interface MessageCandidate {
  original: RuntimeMessage;
  normalized: RuntimeNormalizedMessage | null;
}

export class DefaultExtractionReconciler implements ExtractionReconciler {
  private readonly runtimeValidator = new DefaultRuntimeValidator();

  reconcile(input: ReconciliationInput): ReconciliationOutcome {
    const events: ReconciliationEvent[] = [];
    const fatals: ReconciliationFailure[] = [];

    const counters = {
      inputMessageCount: input.extraction.messages.length,
      outputMessageCount: 0,
      droppedMessageCount: 0,
      inferredRoleCount: 0,
      droppedBlockCount: 0,
      coercedBlockCount: 0,
      rebuiltPlainTextCount: 0,
      droppedArtifactCount: 0,
      orphanArtifactCount: 0,
      duplicateMessageCount: 0
    };

    const actions = {
      usedFallbackTitle: false,
      usedFallbackExtraction: input.extraction.page.extractionMethod !== "internal_fetch",
      usedMixedExtraction: input.extraction.page.extractionMethod === "mixed",
      reorderedMessages: false,
      rebuiltPlainText: false,
      synthesizedSlug: false
    };

    const runtimeIssues = this.runtimeValidator.validateExtractionResult(input.extraction);
    for (const issue of runtimeIssues) {
      events.push({
        code: issue.code,
        severity: "warning",
        message: issue.message,
        recoverable: true,
        entityType: "export"
      });
    }

    if (input.policy.failOnZeroMessages && input.extraction.messages.length === 0) {
      fatals.push({
        code: "no_messages_extracted",
        message: "No messages were extracted from the provider page."
      });
      return this.failed(input, events, fatals, counters, actions);
    }

    const conversationTitle = this.resolveTitle(input, events, actions);
    if (!conversationTitle) {
      fatals.push({ code: "missing_conversation_title", message: "Conversation title could not be resolved." });
      return this.failed(input, events, fatals, counters, actions);
    }

    const slug = input.policy.synthesizeSlugFromTitle ? slugify(conversationTitle) : conversationTitle;
    if (!slug) {
      fatals.push({ code: "title_fallback_used", message: "Slug generation failed." });
      return this.failed(input, events, fatals, counters, actions);
    }
    actions.synthesizedSlug = true;

    const deduped = this.dedupeMessages(input.extraction.messages, counters, events, input.policy.preferHigherQualityExtractionMethod);
    const normalizedMessages = deduped
      .map((message) => this.normalizeMessage(message, input, counters, events))
      .flatMap((candidate) => (candidate.normalized ? [candidate.normalized] : []));

    if (normalizedMessages.length === 0) {
      fatals.push({ code: "no_messages_extracted", message: "All extracted messages were dropped during reconciliation." });
      return this.failed(input, events, fatals, counters, actions);
    }

    const orderedMessages = this.orderMessages(deduped, normalizedMessages, input, events);
    if (orderedMessages.changed) {
      actions.reorderedMessages = true;
    }

    const finalMessages = orderedMessages.messages;
    counters.outputMessageCount = finalMessages.length;
    actions.rebuiltPlainText = counters.rebuiltPlainTextCount > 0;

    const artifacts = this.normalizeArtifacts(input.extraction.artifacts, finalMessages, input, counters, events);

    const conversationWarnings = [...input.extraction.warnings];
    if (actions.usedFallbackExtraction) {
      conversationWarnings.push({
        code: "fallback_extraction_used",
        message: "A fallback extraction method was used instead of the preferred extraction path.",
        recoverable: true,
        severity: "warning"
      });
      events.push({
        code: "fallback_extraction_used",
        severity: "warning",
        message: "A fallback extraction method was used instead of the preferred extraction path.",
        recoverable: true,
        entityType: "export"
      });
    }

    if (actions.usedMixedExtraction) {
      conversationWarnings.push({
        code: "mixed_extraction_used",
        message: "Content was combined from multiple extraction methods.",
        recoverable: true,
        severity: "warning"
      });
      events.push({
        code: "mixed_extraction_used",
        severity: "warning",
        message: "Content was combined from multiple extraction methods.",
        recoverable: true,
        entityType: "export"
      });
    }

    const partial = counters.droppedMessageCount > 0 || counters.droppedBlockCount > 0 || counters.droppedArtifactCount > 0 || actions.usedFallbackExtraction;
    if (partial) {
      conversationWarnings.push({
        code: "partial_export",
        message: "Some content was dropped or transformed during reconciliation.",
        recoverable: true,
        severity: "warning"
      });
      events.push({
        code: "partial_export",
        severity: "warning",
        message: "Some content was dropped or transformed during reconciliation.",
        recoverable: true,
        entityType: "export"
      });
    }

    const normalizedConversation: RuntimeNormalizedConversation = {
      provider: input.extraction.conversation.provider,
      extractionMethod: input.extraction.page.extractionMethod,
      conversationId: input.extraction.conversation.conversationId ?? null,
      url: input.extraction.conversation.url ?? input.extraction.page.pageUrl,
      title: conversationTitle,
      slug,
      createdAt: normalizeIsoTimestamp(input.extraction.conversation.createdAt),
      updatedAt: normalizeIsoTimestamp(input.extraction.conversation.updatedAt),
      workspace: input.extraction.conversation.workspace ?? null,
      tags: [],
      project: null,
      summary: null,
      messages: finalMessages,
      artifacts,
      warnings: conversationWarnings
    };

    return {
      status: partial ? "partial" : "success",
      success: true,
      partial,
      policy: input.policy,
      normalizedConversation,
      events,
      warnings: events.filter((event) => event.severity === "warning"),
      errors: events.filter((event) => event.severity === "error"),
      fatals: [],
      counters,
      actions
    };
  }

  private failed(
    input: ReconciliationInput,
    events: ReconciliationEvent[],
    fatals: ReconciliationFailure[],
    counters: ReconciliationResult["counters"],
    actions: ReconciliationResult["actions"]
  ): ReconciliationOutcome {
    return {
      status: "failed",
      success: false,
      partial: false,
      policy: input.policy,
      normalizedConversation: null,
      events,
      warnings: events.filter((event) => event.severity === "warning"),
      errors: events.filter((event) => event.severity === "error"),
      fatals,
      counters,
      actions
    };
  }

  private resolveTitle(
    input: ReconciliationInput,
    events: ReconciliationEvent[],
    actions: ReconciliationResult["actions"]
  ): string | null {
    const extracted = nonEmptyOrNull(input.extraction.conversation.title);
    const pageTitle = nonEmptyOrNull(input.extraction.page.pageTitle);

    if (extracted && !isPlaceholderTitle(input.extraction.conversation.provider, extracted)) {
      return extracted;
    }

    if (extracted) {
      events.push({
        code: "placeholder_conversation_title",
        severity: "warning",
        message: "Placeholder conversation title was replaced.",
        recoverable: true,
        entityType: "conversation"
      });
    }

    if (pageTitle && !isPlaceholderTitle(input.extraction.conversation.provider, pageTitle)) {
      actions.usedFallbackTitle = true;
      events.push({
        code: "title_fallback_used",
        severity: "warning",
        message: "Page title was used as the fallback conversation title.",
        recoverable: true,
        entityType: "conversation"
      });
      return pageTitle;
    }

    if (input.policy.generateFallbackTitleFromProviderAndTimestamp) {
      actions.usedFallbackTitle = true;
      const fallback = `${input.extraction.conversation.provider}-conversation-${input.extraction.page.capturedAt.replace(/[:.]/g, "-")}`;
      events.push({
        code: "title_fallback_used",
        severity: "warning",
        message: "A synthesized fallback title was generated for this conversation.",
        recoverable: true,
        entityType: "conversation"
      });
      return fallback;
    }

    return null;
  }

  private dedupeMessages(
    messages: RuntimeMessage[],
    counters: ReconciliationResult["counters"],
    events: ReconciliationEvent[],
    preferHigherQuality: boolean
  ): RuntimeMessage[] {
    const byProviderId = new Map<string, RuntimeMessage>();
    const ordered: RuntimeMessage[] = [];

    for (const message of messages) {
      if (!message.providerMessageId) {
        ordered.push(message);
        continue;
      }

      const existing = byProviderId.get(message.providerMessageId);
      if (!existing) {
        byProviderId.set(message.providerMessageId, message);
        ordered.push(message);
        continue;
      }

      counters.duplicateMessageCount += 1;
      events.push({
        code: "duplicate_provider_message_id",
        severity: "warning",
        message: `Duplicate provider message ID detected: ${message.providerMessageId}`,
        recoverable: true,
        entityType: "message",
        entityRuntimeId: message.runtimeId
      });

      if (!preferHigherQuality) {
        ordered.push(message);
        continue;
      }

      const existingRank = METHOD_RANK[existing.sourceMethod];
      const currentRank = METHOD_RANK[message.sourceMethod];
      if (currentRank < existingRank) {
        const index = ordered.findIndex((candidate) => candidate.runtimeId === existing.runtimeId);
        if (index >= 0) {
          ordered[index] = message;
          byProviderId.set(message.providerMessageId, message);
        }
      } else {
        events.push({
          code: "duplicate_message_dropped",
          severity: "warning",
          message: "A lower-quality duplicate message was dropped during reconciliation.",
          recoverable: true,
          entityType: "message",
          entityRuntimeId: message.runtimeId
        });
      }
    }

    return ordered;
  }

  private normalizeMessage(
    message: RuntimeMessage,
    input: ReconciliationInput,
    counters: ReconciliationResult["counters"],
    events: ReconciliationEvent[]
  ): MessageCandidate {
    const role = this.resolveRole(message.role, message, input, counters, events);
    if (!role) {
      counters.droppedMessageCount += 1;
      return { original: message, normalized: null };
    }

    const normalizedBlocks = this.normalizeBlocks(message, input, counters, events);
    if (normalizedBlocks.length === 0 && input.policy.coerceRawTextToTextBlockWhenNoBlocksExist) {
      const fallbackText = nonEmptyOrNull(message.rawText);
      if (fallbackText) {
        normalizedBlocks.push({ type: "text", text: fallbackText });
        counters.coercedBlockCount += 1;
        events.push({
          code: "content_blocks_rebuilt_from_raw_text",
          severity: "warning",
          message: "Message content blocks were rebuilt from raw text.",
          recoverable: true,
          entityType: "message",
          entityRuntimeId: message.runtimeId
        });
      }
    }

    if (normalizedBlocks.length === 0) {
      counters.droppedMessageCount += 1;
      events.push({
        code: "dropped_message_after_block_cleanup",
        severity: "warning",
        message: "Message was dropped after block cleanup left it empty.",
        recoverable: true,
        entityType: "message",
        entityRuntimeId: message.runtimeId
      });
      return { original: message, normalized: null };
    }

    const timestamp = normalizeIsoTimestamp(message.timestamp);
    if (message.timestamp && !timestamp) {
      events.push({
        code: "invalid_timestamp",
        severity: "warning",
        message: "Invalid timestamp was discarded during reconciliation.",
        recoverable: true,
        entityType: "message",
        entityRuntimeId: message.runtimeId
      });
    } else if (!message.timestamp) {
      events.push({
        code: "missing_timestamp",
        severity: "info",
        message: "Message timestamp was unavailable.",
        recoverable: true,
        entityType: "message",
        entityRuntimeId: message.runtimeId
      });
    }

    const plainText = this.buildPlainText(normalizedBlocks);
    counters.rebuiltPlainTextCount += 1;

    const normalized: RuntimeNormalizedMessage = {
      providerMessageId: message.providerMessageId ?? null,
      role,
      displayName: nonEmptyOrNull(message.displayName),
      timestamp,
      contentBlocks: normalizedBlocks,
      plainText,
      sourceMethod: message.sourceMethod,
      warnings: [...message.warnings]
    };

    return { original: message, normalized };
  }

  private resolveRole(
    role: RuntimeRole,
    message: RuntimeMessage,
    input: ReconciliationInput,
    counters: ReconciliationResult["counters"],
    events: ReconciliationEvent[]
  ): Exclude<RuntimeRole, "unknown"> | null {
    if (role !== "unknown") {
      return role;
    }

    if (input.policy.inferUnknownRolesWhenPossible) {
      const displayName = nonEmptyOrNull(message.displayName)?.toLowerCase() ?? "";
      const rawText = nonEmptyOrNull(message.rawText)?.toLowerCase() ?? "";
      if (displayName.includes("assistant") || rawText.startsWith("assistant:")) {
        counters.inferredRoleCount += 1;
        events.push({
          code: "inferred_message_role",
          severity: "info",
          message: "Message role was inferred as assistant.",
          recoverable: true,
          entityType: "message",
          entityRuntimeId: message.runtimeId
        });
        return "assistant";
      }
      if (displayName.includes("user") || displayName.includes("human") || rawText.startsWith("user:")) {
        counters.inferredRoleCount += 1;
        events.push({
          code: "inferred_message_role",
          severity: "info",
          message: "Message role was inferred as human.",
          recoverable: true,
          entityType: "message",
          entityRuntimeId: message.runtimeId
        });
        return "human";
      }
    }

    if (input.policy.unknownRolePolicy === "drop") {
      events.push({
        code: "dropped_unknown_role_message",
        severity: "warning",
        message: "Message with unresolved role was dropped.",
        recoverable: true,
        entityType: "message",
        entityRuntimeId: message.runtimeId
      });
      return null;
    }

    return null;
  }

